-- Knowledge in the database: Arbor Acres norms (editable per farm by the director) and handbook articles.
-- Seed data comes from 20261127000003_knowledge_seed.sql, generated by scripts/gen-knowledge.mjs
-- from packages/core/src/norms/aa-norms.json and docs/knowledge/*.md.

create table public.norm (
  id uuid primary key default gen_random_uuid(),
  farm_id uuid references public.farm (id) on delete cascade,  -- null = Arbor Acres default for every farm
  code text not null,
  data jsonb not null,
  updated_by uuid default auth.uid(),
  updated_at timestamptz not null default now(),
  unique nulls not distinct (farm_id, code)
);

create table public.knowledge_article (
  id text primary key,
  farm_id uuid references public.farm (id) on delete cascade,  -- null = handbook article; farm = director's own note
  section text not null,
  title text not null,
  body_md text not null,
  source text,
  sort int not null default 0,
  updated_at timestamptz not null default now(),
  search tsvector generated always as (to_tsvector('russian', coalesce(title, '') || ' ' || coalesce(body_md, ''))) stored
);
create index knowledge_article_search on public.knowledge_article using gin (search);

alter table public.norm enable row level security;
alter table public.knowledge_article enable row level security;

-- Everyone at the farm reads defaults and the farm's own rows; only the director changes the farm's rows.
create policy norm_read on public.norm for select using (farm_id is null or farm_id = public.current_farm_id());
create policy norm_head_insert on public.norm for insert with check (farm_id = public.current_farm_id() and public.is_head());
create policy norm_head_update on public.norm for update using (farm_id = public.current_farm_id() and public.is_head());
create policy norm_head_delete on public.norm for delete using (farm_id = public.current_farm_id() and public.is_head());

create policy article_read on public.knowledge_article for select using (farm_id is null or farm_id = public.current_farm_id());
create policy article_head_insert on public.knowledge_article for insert with check (farm_id = public.current_farm_id() and public.is_head());
create policy article_head_update on public.knowledge_article for update using (farm_id = public.current_farm_id() and public.is_head());
create policy article_head_delete on public.knowledge_article for delete using (farm_id = public.current_farm_id() and public.is_head());

grant select, insert, update, delete on public.norm, public.knowledge_article to authenticated;
revoke all on public.norm, public.knowledge_article from anon;

/** Full-text search over the handbook (Russian stemming), best matches first. Used by the app and the assistant. */
create or replace function public.search_knowledge(q text, max_results int default 8)
returns table (id text, section text, title text, body_md text, rank real)
language sql stable security invoker set search_path = public as $$
  select a.id, a.section, a.title, a.body_md, ts_rank(a.search, websearch_to_tsquery('russian', q)) as rank
  from public.knowledge_article a
  where a.search @@ websearch_to_tsquery('russian', q)
  order by rank desc
  limit max_results
$$;
grant execute on function public.search_knowledge(text, int) to authenticated;

-- Questions to the knowledge assistant: a log for the director and a daily limit per person.
create table public.assistant_question (
  id bigserial primary key,
  farm_id uuid not null default public.current_farm_id() references public.farm (id) on delete cascade,
  user_id uuid not null default auth.uid(),
  question text not null,
  answer text,
  sources text[] not null default '{}',
  input_tokens int,
  output_tokens int,
  created_at timestamptz not null default now()
);
alter table public.assistant_question enable row level security;
create policy aq_own_read on public.assistant_question for select using (user_id = auth.uid() or (farm_id = public.current_farm_id() and public.is_head()));
create policy aq_own_insert on public.assistant_question for insert with check (user_id = auth.uid() and farm_id = public.current_farm_id());
grant select, insert on public.assistant_question to authenticated;
grant usage on sequence public.assistant_question_id_seq to authenticated;

/** Search with any of the words (questions are natural language, not keyword lists). */
create or replace function public.search_knowledge_any(q text, max_results int default 8)
returns table (id text, section text, title text, body_md text, rank real)
language sql stable security invoker set search_path = public as $$
  with words as (
    select string_agg(w, ' or ') as wq
    from regexp_split_to_table(lower(q), '[^[:alnum:]]+') as w
    where length(w) >= 3
  )
  select a.id, a.section, a.title, a.body_md, ts_rank(a.search, websearch_to_tsquery('russian', words.wq)) as rank
  from public.knowledge_article a, words
  where words.wq is not null and a.search @@ websearch_to_tsquery('russian', words.wq)
  order by rank desc
  limit max_results
$$;
grant execute on function public.search_knowledge_any(text, int) to authenticated;
